import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'addStaleLabels',
  context: {
    owner: 'acme',
    repo: 'widgets',
    issues: [],
    staleIssues: [],
    updates: [],
    results: [],
    skipped: [],
    failed: [],
  },
  initial: 'fetchingIssues',
  states: {
    fetchingIssues: {
      entry: toolCall('github.list_issues', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'OPEN',
        perPage: 100,
        fields: ['number', 'updated_at', 'labels'],
      })),
      on: {
        TOOL_RESULT: {
          target: 'filteringStaleIssues',
          actions: assign({
            issues: ({ event }) => event.result.issues || [],
          }),
        },
        TOOL_ERROR: 'done',
      },
    },
    filteringStaleIssues: {
      always: {
        target: 'updatingStaleIssues',
        actions: assign({
          staleIssues: ({ context }) => {
            const cutoffDate = new Date('2026-07-01');
            return context.issues.filter(issue => {
              const updatedAt = new Date(issue.updated_at);
              return updatedAt < cutoffDate;
            });
          },
        }),
      },
    },
    updatingStaleIssues: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.staleIssues.forEach((issue, i) => {
          const currentLabels = issue.labels || [];
          const hasStaleLabel = currentLabels.some(l => l === 'stale' || (typeof l === 'object' && l.name === 'stale'));

          // If stale label already exists, skip
          if (hasStaleLabel) {
            return;
          }

          const labelNames = currentLabels.map(l => typeof l === 'object' ? l.name : l);
          labelNames.push('stale');

          enqueue(toolCall(
            'github.issue_write',
            {
              owner: context.owner,
              repo: context.repo,
              method: 'update',
              issue_number: issue.number,
              labels: labelNames,
            },
            { id: `update_${i}` }
          ));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            results: ({ context, event }) => [...context.results, event.callId],
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            skipped: ({ context, event }) => [...context.skipped, event.callId],
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            failed: ({ context, event }) => [...context.failed, event.callId],
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const totalCalls = context.staleIssues.length;
          const answered = context.results.length + context.skipped.length + context.failed.length;
          return answered === totalCalls;
        },
        target: 'done',
      },
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    totalStaleIssues: context.staleIssues.length,
    updated: context.results.length,
    skipped: context.skipped.length,
    failed: context.failed.length,
    staleIssueNumbers: context.staleIssues.map(i => i.number),
  }),
});

