        state: 'OPEN',
        perPage: 100,
        fields: ['number', 'updated_at', 'labels'],
      })),
      on: {
        TOOL_RESULT: {
          target: 'filteringStaleIssues',
          actions: assign({
            issues: ({ event }) => event.result.issues || [],
