export default setup({}).createMachine({
  id: 'postChangelogComments',
  context: {
    owner: 'acme',
    repo: 'widgets',
    openPRs: [],
    prFilesMap: {},
    prNumbersToComment: [],
    commentedPRs: [],
    skippedPRs: [],
    failedPRs: [],
  },
  initial: 'listingOpenPRs',
  states: {
    listingOpenPRs: {
      entry: toolCall('github.list_pull_requests', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'open',
        fields: ['number', 'title', 'state'],
      })),
      on: {
        TOOL_RESULT: {
          target: 'fetchingFileChanges',
          actions: assign({
            openPRs: ({ event }) => event.result || [],
          }),
        },
        TOOL_ERROR: {
          target: 'done',
          actions: assign({
            openPRs: [],
          }),
        },
      },
    },

    fetchingFileChanges: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.openPRs.forEach((pr, index) => {
          if (typeof pr === 'object' && pr.number) {
            enqueue(
              toolCall(
                'github.pull_request_read',
                {
                  owner: context.owner,
                  repo: context.repo,
                  pullNumber: pr.number,
                  method: 'get_files',
                  perPage: 100,
                },
                { id: `pr_${pr.number}` }
              )
            );
          }
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            prFilesMap: ({ context, event }) => {
              const prNumber = parseInt(event.callId.replace('pr_', ''));
              return {
                ...context.prFilesMap,
                [prNumber]: event.result || [],
              };
            },
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            prFilesMap: ({ context, event }) => {
              const prNumber = parseInt(event.callId.replace('pr_', ''));
              return {
                ...context.prFilesMap,
                [prNumber]: [],
              };
            },
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const fetchedCount = Object.keys(context.prFilesMap).length;
          return fetchedCount === context.openPRs.length;
        },
        target: 'filteringPRs',
      },
    },

    filteringPRs: {
      entry: assign({
        prNumbersToComment: ({ context }) => {
          const toComment = [];
          context.openPRs.forEach((pr) => {
            if (typeof pr === 'object' && pr.number) {
              const files = context.prFilesMap[pr.number] || [];
              const hasExportChanges = files.some((file) =>
                file.filename && file.filename.startsWith('src/export/')
              );
              if (hasExportChanges) {
                toComment.push(pr.number);
              }
            }
          });
          return toComment;
        },
      }),
      always: 'postingComments',
    },

    postingComments: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.prNumbersToComment.forEach((prNumber) => {
          enqueue(
            toolCall(
              'github.add_issue_comment',
              {
                owner: context.owner,
                repo: context.repo,
                issue_number: prNumber,
                body: 'Please add a CHANGELOG entry for the export changes.',
              },
              { id: `comment_${prNumber}` }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            commentedPRs: ({ context, event }) => [
              ...context.commentedPRs,
              parseInt(event.callId.replace('comment_', '')),
            ],
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            skippedPRs: ({ context, event }) => [
              ...context.skippedPRs,
              parseInt(event.callId.replace('comment_', '')),
            ],
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            failedPRs: ({ context, event }) => [
              ...context.failedPRs,
              parseInt(event.callId.replace('comment_', '')),
            ],
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const processedCount =
            context.commentedPRs.length +
            context.skippedPRs.length +
            context.failedPRs.length;
          return processedCount === context.prNumbersToComment.length;
        },
        target: 'done',
      },
    },

    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    commentedPRs: context.commentedPRs,
    skippedPRs: context.skippedPRs,
    failedPRs: context.failedPRs,
    prNumbersToComment: context.prNumbersToComment,
  }),
});

