        TOOL_RESULT: {
          actions: assign({
            prFilesMap: ({ context, event }) => {
              const prNumber = parseInt(event.callId.replace('pr_', ''));
              let files = [];
              if (Array.isArray(event.result)) {
                files = event.result;
              } else if (typeof event.result === 'string') {
                files = JSON.parse(event.result);
              }
              return {
                ...context.prFilesMap,
                [prNumber]: files,
              };
            },
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            prFilesMap: ({ context, event }) => {
              const prNumber = parseInt(event.callId.replace('pr_', ''));
              return {
                ...context.prFilesMap,
                [prNumber]: [],
              };
            },
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const fetchedCount = Object.keys(context.prFilesMap).length;
          return fetchedCount === context.openPRs.length;
        },
        target: 'filteringPRs',
      },
    },

    filteringPRs: {
      entry: assign({
        prNumbersToComment: ({ context }) => {
          const toComment = [];
          if (!Array.isArray(context.openPRs)) {
            return toComment;
          }
          context.openPRs.forEach((pr) => {
            if (typeof pr === 'object' && pr.number) {
              const files = context.prFilesMap[pr.number] || [];
              const hasExportChanges = files.some((file) =>
                file && file.filename && file.filename.startsWith('src/export/')
              );
              if (hasExportChanges) {
                toComment.push(pr.number);
              }
            }
          });
          return toComment;
        },
      }),
      always: 'postingComments',
    },

    postingComments: {
      entry: enqueueActions(({ context, enqueue }) => {
        if (context.prNumbersToComment.length === 0) {
          return;
        }
        context.prNumbersToComment.forEach((prNumber) => {
          enqueue(
            toolCall(
              'github.add_issue_comment',
              {
                owner: context.owner,
                repo: context.repo,
                issue_number: prNumber,
                body: 'Please add a CHANGELOG entry for the export changes.',
              },
              { id: `comment_${prNumber}` }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            commentedPRs: ({ context, event }) => [
              ...context.commentedPRs,
              parseInt(event.callId.replace('comment_', '')),
            ],
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            skippedPRs: ({ context, event }) => [
              ...context.skippedPRs,
              parseInt(event.callId.replace('comment_', '')),
            ],
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            failedPRs: ({ context, event }) => [
              ...context.failedPRs,
              parseInt(event.callId.replace('comment_', '')),
            ],
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          if (context.prNumbersToComment.length === 0) {
            return true;
          }
          const processedCount =
            context.commentedPRs.length +
            context.skippedPRs.length +
            context.failedPRs.length;
          return processedCount === context.prNumbersToComment.length;
        },
        target: 'done',
      },
    },

    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
