});

import { setup, assign, enqueueActions } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'syncAuditLogs',
  context: {
    shippedOrders: [],
    auditLogs: [],
    missingLogs: [],
    insertedCount: 0,
  },
  initial: 'fetchShippedOrders',
  states: {
    fetchShippedOrders: {
      entry: toolCall('mongo.find', {
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'orders',
        filter: { status: 'shipped' },
        projection: { orderId: 1 },
      }),
      on: {
        TOOL_RESULT: {
          target: 'fetchExistingAuditLogs',
          actions: assign({
            shippedOrders: ({ event }) => event.result.documents || [],
          }),
        },
        TOOL_ERROR: { target: 'failed' },
      },
    },
    fetchExistingAuditLogs: {
      entry: toolCall('mongo.find', {
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'audit_log',
        filter: { action: 'shipped' },
        projection: { orderId: 1 },
      }),
      on: {
        TOOL_RESULT: {
          target: 'identifyMissing',
          actions: assign({
            auditLogs: ({ event }) => event.result.documents || [],
          }),
        },
        TOOL_ERROR: { target: 'failed' },
      },
    },
    identifyMissing: {
      entry: assign({
        missingLogs: ({ context }) => {
          const existingOrderIds = new Set(
            context.auditLogs.map(log => String(log.orderId))
          );
          return context.shippedOrders
            .filter(order => !existingOrderIds.has(String(order.orderId)))
            .map(order => ({
              orderId: order.orderId,
              action: 'shipped',
            }));
        },
      }),
      always: {
        guard: ({ context }) => context.missingLogs.length > 0,
        target: 'insertMissing',
      },
        on: {
          // If there are no missing logs, go to done
        },
      },
      type: 'compound',
      initial: 'checking',
      states: {
        checking: {
          always: [
            {
              guard: ({ context }) => context.missingLogs.length > 0,
              target: '#insertMissing',
            },
            {
              target: '#done',
            },
          ],
        },
      },
    },
    insertMissing: {
      id: 'insertMissing',
      entry: toolCall('mongo.insert-many', ({ context }) => ({
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'audit_log',
        documents: context.missingLogs,
      })),
      on: {
        TOOL_RESULT: {
          target: 'done',
          actions: assign({
            insertedCount: ({ event }) => event.result.insertedCount,
          }),
        },
        TOOL_DENIED: {
          target: 'done',
          actions: assign({
            insertedCount: 0,
          }),
        },
        TOOL_ERROR: { target: 'failed' },
      },
    },
    done: {
      id: 'done',
      type: 'final',
    },
    failed: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    shippedOrdersCount: context.shippedOrders.length,
    existingAuditLogsCount: context.auditLogs.length,
    missingLogsCount: context.missingLogs.length,
    insertedCount: context.insertedCount,
  }),
});

