    },
  },
  initial: 'getCheckRuns',
  states: {
    getCheckRuns: {
      entry: toolCall('github.pull_request_read', {
        method: 'get_check_runs',
        owner: 'acme',
        repo: 'widgets',
        pullNumber: 139,
      }),
      on: {
        TOOL_RESULT: {
          target: 'extractFailingFiles',
          actions: assign({
            checkRuns: ({ event }) => event.result.check_runs || [],
          }),
        },
        TOOL_ERROR: 'done',
      },
    },

    extractFailingFiles: {
      always: {
        target: 'checkFileExistence',
        actions: assign({
          failingFiles: ({ context }) => {
            const failingChecks = context.checkRuns.filter(
              check => check.conclusion === 'failure'
            );

            const files = new Set();
            failingChecks.forEach(check => {
              const summary = check.output?.summary || '';

              // Extract file path from summary
              // Patterns: "in src/...", "Broken link in docs/...", etc.
              const patterns = [
                /in ([\w\/.]+\.\w+)/,  // "in src/api/routes.ts"
                /Broken link in ([\w\/.]+)/,  // "Broken link in docs/api.md"
                /Snapshot mismatch in ([\w\/.]+\.\w+)/,  // "Snapshot mismatch in src/ui/chart.tsx"
                /Timeout in ([\w\/.]+\.\w+)/,  // "Timeout in src/export/pdf.ts"
                /Regression in ([\w\/.]+\.\w+)/,  // "Regression in src/perf/bench.ts"
                /Missing header in ([\w\/.]+\.\w+)/,  // "Missing header in scripts/license.sh"
                /([\w\/.]+\.\w+):\d+:\d+/,  // "src/api/routes.ts:42:7"
              ];

              for (const pattern of patterns) {
                const match = summary.match(pattern);
                if (match && match[1]) {
                  files.add(match[1]);
                  break;
                }
              }
            });

            return Array.from(files);
          },
        }),
      },
    },

    checkFileExistence: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.failingFiles.forEach((file, i) => {
          enqueue(toolCall('fs.get_file_info', { path: file }, { id: `check_${i}` }));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            fileExistenceMap: ({ context, event }) => ({
              ...context.fileExistenceMap,
              [event.callId]: { exists: true },
            }),
            fileChecksCompleted: ({ context }) => context.fileChecksCompleted + 1,
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            fileExistenceMap: ({ context, event }) => ({
              ...context.fileExistenceMap,
              [event.callId]: { exists: false },
            }),
            fileChecksCompleted: ({ context }) => context.fileChecksCompleted + 1,
          }),
        },
      },
      always: {
        guard: ({ context }) =>
          context.fileChecksCompleted === context.failingFiles.length,
        target: 'executeActions',
      },
    },

    executeActions: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.failingFiles.forEach((file, i) => {
          const checkId = `check_${i}`;
          const fileExists = context.fileExistenceMap[checkId]?.exists;

          if (fileExists) {
            // File exists: create an issue
            enqueue(toolCall(
              'github.issue_write',
              {
                method: 'create',
                owner: context.owner,
                repo: context.repo,
                title: `Fix ${file}`,
              },
              { id: `action_${i}` }
            ));
          } else {
            // File doesn't exist: comment on PR
            enqueue(toolCall(
              'github.add_issue_comment',
              {
                owner: context.owner,
                repo: context.repo,
                issue_number: context.prNumber,
                body: `Missing file: ${file}`,
              },
              { id: `action_${i}` }
            ));
          }
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            results: ({ context, event }) => ({
              ...context.results,
              issuesCreated: [
                ...context.results.issuesCreated,
                event.callId,
              ],
            }),
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            results: ({ context, event }) => ({
              ...context.results,
              issuesCreated: [
                ...context.results.issuesCreated,
                `${event.callId}_denied`,
              ],
            }),
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            results: ({ context, event }) => ({
              ...context.results,
              issuesCreated: [
                ...context.results.issuesCreated,
                `${event.callId}_error`,
              ],
            }),
          }),
        },
      },
      always: {
        guard: ({ context }) =>
          context.results.issuesCreated.length === context.failingFiles.length,
        target: 'done',
      },
    },

    done: {
      type: 'final',
    },
  },
});

