          context.fileChecksCompleted === context.failingFiles.length,
        target: 'executeActions',
      },
    },

    executeActions: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.failingFiles.forEach((file, i) => {
          const checkId = `check_${i}`;
          const fileExists = context.fileExistenceMap[checkId];

          if (fileExists) {
            // File exists: create an issue
            enqueue(toolCall(
              'github.issue_write',
              {
                method: 'create',
                owner: context.owner,
                repo: context.repo,
                title: `Fix ${file}`,
              },
              { id: `action_${i}` }
            ));
          } else {
            // File doesn't exist: comment on PR
            enqueue(toolCall(
              'github.add_issue_comment',
              {
                owner: context.owner,
                repo: context.repo,
                issue_number: context.prNumber,
                body: `Missing file: ${file}`,
              },
              { id: `action_${i}` }
            ));
          }
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            actionDetails: ({ context, event }) => [
              ...context.actionDetails,
              { callId: event.callId, status: 'success' },
            ],
            actionsCompleted: ({ context }) => context.actionsCompleted + 1,
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            actionDetails: ({ context, event }) => [
              ...context.actionDetails,
              { callId: event.callId, status: 'denied' },
            ],
            actionsCompleted: ({ context }) => context.actionsCompleted + 1,
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            actionDetails: ({ context, event }) => [
              ...context.actionDetails,
              { callId: event.callId, status: 'error' },
            ],
            actionsCompleted: ({ context }) => context.actionsCompleted + 1,
          }),
        },
      },
      always: {
        guard: ({ context }) =>
          context.actionsCompleted === context.failingFiles.length,
        target: 'done',
      },
    },

    done: {
      type: 'final',
      output: ({ context }) => ({
        failingFiles: context.failingFiles,
        fileExistenceMap: context.fileExistenceMap,
        actionDetails: context.actionDetails,
      }),
    },
  },
});

