import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'handleFailingChecks',
  context: {
    owner: 'acme',
    repo: 'widgets',
    prNumber: 139,
    checkRuns: [],
    failingFiles: [],
    fileExistenceChecks: [],
    issuesToCreate: [],
    commentsToCreate: [],
  },
  initial: 'getCheckRuns',
  states: {
    getCheckRuns: {
      entry: toolCall('github.pull_request_read', ({ context }) => ({
        method: 'get_check_runs',
        owner: context.owner,
        repo: context.repo,
        pullNumber: context.prNumber,
      })),
      on: {
        TOOL_RESULT: {
          target: 'processCheckRuns',
          actions: assign({
            checkRuns: ({ event }) => {
              const result = event.result;
              // Handle different possible result formats
              let runs = Array.isArray(result) ? result : 
                         result?.check_runs ? result.check_runs :
                         result?.checkRuns ? result.checkRuns : [];
              return runs;
            },
          }),
        },
        TOOL_ERROR: 'done',
      },
    },

    processCheckRuns: {
      always: {
        target: 'checkFileExistence',
        actions: assign({
          failingFiles: ({ context }) => {
            const failingChecks = context.checkRuns.filter(
              check => check.conclusion === 'failure' || check.conclusion === 'failed'
            );

            // Extract file paths from check output/summary
            const files = [];
            failingChecks.forEach(check => {
              // Try to extract file path from various possible fields
              let file = null;

              if (check.output?.title) {
                const title = check.output.title;
                // Try to extract file path from title
                const match = title.match(/^(?:Fix |File: |Error in: )?(.+)$/);
                if (match) {
                  file = match[1];
                }
              }

              if (!file && check.output?.summary) {
                const summary = check.output.summary;
                const match = summary.match(/^(?:Fix |File: |Error in: )?(.+?)(?:\s|$)/);
                if (match) {
                  file = match[1];
                }
              }

              if (!file && check.name) {
                // Use check name as fallback
                file = check.name;
              }

              if (file) {
                files.push(file);
              }
            });

            return files;
          },
        }),
      },
    },

    checkFileExistence: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.failingFiles.forEach((file, i) => {
          enqueue(toolCall('fs.get_file_info', { path: file }, { id: `exists_${i}` }));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            fileExistenceChecks: ({ context, event }) => [
              ...context.fileExistenceChecks,
              {
                callId: event.callId,
                exists: true,
              },
            ],
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            fileExistenceChecks: ({ context, event }) => [
              ...context.fileExistenceChecks,
              {
                callId: event.callId,
                exists: false,
              },
            ],
          }),
        },
      },
      always: {
        guard: ({ context }) =>
          context.fileExistenceChecks.length === context.failingFiles.length,
        target: 'planActions',
      },
    },

    planActions: {
      always: {
        target: 'executeActions',
        actions: assign({
          issuesToCreate: ({ context }) => {
            const issues = [];
            context.failingFiles.forEach((file, i) => {
              const check = context.fileExistenceChecks[i];
              if (check.exists) {
                issues.push({
                  title: `Fix ${file}`,
                  file: file,
                });
              }
            });
            return issues;
          },
          commentsToCreate: ({ context }) => {
            const comments = [];
            context.failingFiles.forEach((file, i) => {
              const check = context.fileExistenceChecks[i];
              if (!check.exists) {
                comments.push({
                  file: file,
                });
              }
            });
            return comments;
          },
        }),
      },
    },

    executeActions: {
      entry: enqueueActions(({ context, enqueue }) => {
        // Create issues for existing files
        context.issuesToCreate.forEach((issue, i) => {
          enqueue(toolCall(
            'github.issue_write',
            {
              method: 'create',
              owner: context.owner,
              repo: context.repo,
              title: issue.title,
            },
            { id: `issue_${i}` }
          ));
        });

        // Create comments for missing files
        context.commentsToCreate.forEach((comment, i) => {
          enqueue(toolCall(
            'github.add_issue_comment',
            {
              owner: context.owner,
              repo: context.repo,
              issue_number: context.prNumber,
              body: `Missing file: ${comment.file}`,
            },
            { id: `comment_${i}` }
          ));
        });
      }),
      on: {
        TOOL_RESULT: {},
        TOOL_DENIED: {},
        TOOL_ERROR: {},
      },
      always: {
        guard: ({ context }) => {
          const totalActions = context.issuesToCreate.length + context.commentsToCreate.length;
          // This would be a simplification - in a real scenario we'd track results
          return true;
        },
        target: 'done',
      },
    },

    done: {
      type: 'final',
    },
  },
});

import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'handleFailingChecks',
  context: {
    owner: 'acme',
    repo: 'widgets',
    prNumber: 139,
    checkRuns: [],
    failingFiles: [],
    fileChecksCompleted: 0,
    fileExistenceMap: {},
    results: {
      issuesCreated: [],
      commentsAdded: [],
    },
  },
  initial: 'getCheckRuns',
  states: {
    getCheckRuns: {
      entry: toolCall('github.pull_request_read', {
        method: 'get_check_runs',
        owner: 'acme',
        repo: 'widgets',
        pullNumber: 139,
      }),
      on: {
        TOOL_RESULT: {
          target: 'extractFailingFiles',
          actions: assign({
            checkRuns: ({ event }) => event.result.check_runs || [],
          }),
        },
        TOOL_ERROR: 'done',
      },
    },

    extractFailingFiles: {
      always: {
        target: 'checkFileExistence',
        actions: assign({
          failingFiles: ({ context }) => {
            const failingChecks = context.checkRuns.filter(
              check => check.conclusion === 'failure'
            );

            const files = new Set();
            failingChecks.forEach(check => {
              const summary = check.output?.summary || '';

              // Extract file path from summary
              // Patterns: "in src/...", "Broken link in docs/...", etc.
              const patterns = [
                /in ([\w\/.]+\.\w+)/,  // "in src/api/routes.ts"
                /Broken link in ([\w\/.]+)/,  // "Broken link in docs/api.md"
                /Snapshot mismatch in ([\w\/.]+\.\w+)/,  // "Snapshot mismatch in src/ui/chart.tsx"
                /Timeout in ([\w\/.]+\.\w+)/,  // "Timeout in src/export/pdf.ts"
                /Regression in ([\w\/.]+\.\w+)/,  // "Regression in src/perf/bench.ts"
                /Missing header in ([\w\/.]+\.\w+)/,  // "Missing header in scripts/license.sh"
                /([\w\/.]+\.\w+):\d+:\d+/,  // "src/api/routes.ts:42:7"
              ];

              for (const pattern of patterns) {
                const match = summary.match(pattern);
                if (match && match[1]) {
                  files.add(match[1]);
                  break;
                }
              }
            });

            return Array.from(files);
          },
        }),
      },
    },

    checkFileExistence: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.failingFiles.forEach((file, i) => {
          enqueue(toolCall('fs.get_file_info', { path: file }, { id: `check_${i}` }));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            fileExistenceMap: ({ context, event }) => ({
              ...context.fileExistenceMap,
              [event.callId]: { exists: true },
            }),
            fileChecksCompleted: ({ context }) => context.fileChecksCompleted + 1,
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            fileExistenceMap: ({ context, event }) => ({
              ...context.fileExistenceMap,
              [event.callId]: { exists: false },
            }),
            fileChecksCompleted: ({ context }) => context.fileChecksCompleted + 1,
          }),
        },
      },
      always: {
        guard: ({ context }) =>
          context.fileChecksCompleted === context.failingFiles.length,
        target: 'executeActions',
      },
    },

    executeActions: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.failingFiles.forEach((file, i) => {
          const checkId = `check_${i}`;
          const fileExists = context.fileExistenceMap[checkId]?.exists;

          if (fileExists) {
            // File exists: create an issue
            enqueue(toolCall(
              'github.issue_write',
              {
                method: 'create',
                owner: context.owner,
                repo: context.repo,
                title: `Fix ${file}`,
              },
              { id: `action_${i}` }
            ));
          } else {
            // File doesn't exist: comment on PR
            enqueue(toolCall(
              'github.add_issue_comment',
              {
                owner: context.owner,
                repo: context.repo,
                issue_number: context.prNumber,
                body: `Missing file: ${file}`,
              },
              { id: `action_${i}` }
            ));
          }
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            results: ({ context, event }) => ({
              ...context.results,
              issuesCreated: [
                ...context.results.issuesCreated,
                event.callId,
              ],
            }),
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            results: ({ context, event }) => ({
              ...context.results,
              issuesCreated: [
                ...context.results.issuesCreated,
                `${event.callId}_denied`,
              ],
            }),
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            results: ({ context, event }) => ({
              ...context.results,
              issuesCreated: [
                ...context.results.issuesCreated,
                `${event.callId}_error`,
              ],
            }),
          }),
        },
      },
      always: {
        guard: ({ context }) =>
          context.results.issuesCreated.length === context.failingFiles.length,
        target: 'done',
      },
    },

    done: {
      type: 'final',
    },
  },
});

