import { setup, assign, enqueueActions } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'createFixIssuesAndComments',
  context: {
    existingFiles: [
      'src/api/routes.ts',
      'src/db/pool.ts', 
      'src/export/xml.ts',
      'src/cli/args.ts',
      'src/ui/chart.tsx',
      'docs/api.md',
    ],
    missingFiles: [
      'src/cache/lru.ts',
      'src/export/pdf.ts',
      'src/perf/bench.ts',
      'scripts/license.sh',
    ],
    completedCount: 0,
  },
  initial: 'createIssuesAndComments',
  states: {
    createIssuesAndComments: {
      entry: enqueueActions(({ context, enqueue }) => {
        // Create an issue for each existing file
        context.existingFiles.forEach((file, i) => {
          enqueue(toolCall(
            'github.issue_write',
            {
              method: 'create',
              owner: 'acme',
              repo: 'widgets',
              title: `Fix ${file}`,
            },
            { id: `issue_${i}` }
          ));
        });

        // Add a comment for each missing file
        context.missingFiles.forEach((file, i) => {
          enqueue(toolCall(
            'github.add_issue_comment',
            {
              owner: 'acme',
              repo: 'widgets',
              issue_number: 139,
              body: `Missing file: ${file}`,
            },
            { id: `comment_${i}` }
          ));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            completedCount: ({ context }) => context.completedCount + 1,
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            completedCount: ({ context }) => context.completedCount + 1,
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            completedCount: ({ context }) => context.completedCount + 1,
          }),
        },
      },
      always: {
        guard: ({ context }) =>
          context.completedCount ===
          context.existingFiles.length + context.missingFiles.length,
        target: 'done',
      },
    },
    done: {
      type: 'final',
      output: ({ context }) => ({
        message: 'Completed creating issues and adding comments',
        issuesCreated: context.existingFiles.length,
        commentsAdded: context.missingFiles.length,
      }),
    },
  },
});

import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'processVIPs',
  context: {
    vipEmails: [],
    existingCustomers: [],
    missingEmails: [],
    updateCallIds: [],
    writeStatus: null,
  },
  initial: 'readVipFile',
  states: {
    readVipFile: {
      entry: toolCall('fs.read_file', { path: 'notes/vip.txt' }),
      on: {
        TOOL_RESULT: {
          target: 'parseEmails',
          actions: assign({
            vipEmails: ({ event }) => {
              const content = event.result.content;
              return content
                .split('\n')
                .map(line => line.trim())
                .filter(line => line.length > 0);
            },
          }),
        },
        TOOL_ERROR: {
          target: 'done',
          actions: assign({ writeStatus: 'error reading vip.txt' }),
        },
      },
    },
    parseEmails: {
      always: {
        target: 'checkCustomers',
      },
    },
    checkCustomers: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.vipEmails.forEach((email, i) => {
          enqueue(
            toolCall(
              'mongo.find',
              {
                connectionId: 'preconfigured',
                database: 'shop',
                collection: 'customers',
                filter: { email: email },
              },
              { id: `find_${i}` }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            existingCustomers: ({ context, event }) => {
              const idx = parseInt(event.callId.split('_')[1]);
              const email = context.vipEmails[idx];
              const result = event.result;
              if (result.documents && result.documents.length > 0) {
                return [...context.existingCustomers, { email, doc: result.documents[0] }];
              }
              return context.existingCustomers;
            },
            missingEmails: ({ context, event }) => {
              const idx = parseInt(event.callId.split('_')[1]);
              const email = context.vipEmails[idx];
              const result = event.result;
              if (!result.documents || result.documents.length === 0) {
                return [...context.missingEmails, email];
              }
              return context.missingEmails;
            },
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            missingEmails: ({ context, event }) => {
              const idx = parseInt(event.callId.split('_')[1]);
              return [...context.missingEmails, context.vipEmails[idx]];
            },
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const totalChecks = context.vipEmails.length;
          const resultsReceived =
            context.existingCustomers.length + context.missingEmails.length;
          return resultsReceived === totalChecks;
        },
        target: 'updateGoldTier',
      },
    },
    updateGoldTier: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.existingCustomers.forEach((customer, i) => {
          enqueue(
            toolCall(
              'mongo.update-many',
              {
                connectionId: 'preconfigured',
                database: 'shop',
                collection: 'customers',
                filter: { email: customer.email },
                update: { $set: { tier: 'gold' } },
              },
              { id: `update_${i}` }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            updateCallIds: ({ context, event }) => [
              ...context.updateCallIds,
              event.callId,
            ],
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            updateCallIds: ({ context, event }) => [
              ...context.updateCallIds,
              event.callId,
            ],
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            updateCallIds: ({ context, event }) => [
              ...context.updateCallIds,
              event.callId,
            ],
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          return context.updateCallIds.length === context.existingCustomers.length;
        },
        target: 'writeMissingVips',
      },
    },
    writeMissingVips: {
      entry: toolCall('fs.write_file', ({ context }) => ({
        path: 'notes/missing-vips.txt',
        content: context.missingEmails.join('\n') + (context.missingEmails.length > 0 ? '\n' : ''),
      })),
      on: {
        TOOL_RESULT: {
          target: 'done',
          actions: assign({ writeStatus: 'success' }),
        },
        TOOL_DENIED: {
          target: 'done',
          actions: assign({ writeStatus: 'write denied' }),
        },
        TOOL_ERROR: {
          target: 'done',
          actions: assign({ writeStatus: 'write error' }),
        },
      },
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    vipEmailsProcessed: context.vipEmails.length,
    goldTierUpdated: context.existingCustomers.length,
    missingVipsFound: context.missingEmails.length,
    missingVips: context.missingEmails,
    writeStatus: context.writeStatus,
  }),
});

