        target: 'checkCustomers',
      },
    },
    checkCustomers: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.vipEmails.forEach((email, i) => {
          enqueue(
            toolCall(
              'mongo.find',
              {
                connectionId: 'preconfigured',
                database: 'shop',
                collection: 'customers',
                filter: { email: email },
              },
              { id: `find_${i}` }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            existingCustomers: ({ context, event }) => {
              const idx = parseInt(event.callId.split('_')[1]);
              const email = context.vipEmails[idx];
              const result = event.result;
              if (result.documents && result.documents.length > 0) {
                return [...context.existingCustomers, { email, doc: result.documents[0] }];
              }
              return context.existingCustomers;
            },
            missingEmails: ({ context, event }) => {
              const idx = parseInt(event.callId.split('_')[1]);
              const email = context.vipEmails[idx];
              const result = event.result;
              if (!result.documents || result.documents.length === 0) {
                return [...context.missingEmails, email];
              }
              return context.missingEmails;
            },
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            missingEmails: ({ context, event }) => {
              const idx = parseInt(event.callId.split('_')[1]);
              return [...context.missingEmails, context.vipEmails[idx]];
            },
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const totalChecks = context.vipEmails.length;
          const resultsReceived =
            context.existingCustomers.length + context.missingEmails.length;
          return resultsReceived === totalChecks;
        },
        target: 'updateGoldTier',
      },
    },
    updateGoldTier: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.existingCustomers.forEach((customer, i) => {
          enqueue(
            toolCall(
              'mongo.update-many',
              {
                connectionId: 'preconfigured',
                database: 'shop',
                collection: 'customers',
                filter: { email: customer.email },
                update: { $set: { tier: 'gold' } },
              },
              { id: `update_${i}` }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            updateCallIds: ({ context, event }) => [
              ...context.updateCallIds,
              event.callId,
            ],
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            updateCallIds: ({ context, event }) => [
              ...context.updateCallIds,
              event.callId,
            ],
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            updateCallIds: ({ context, event }) => [
              ...context.updateCallIds,
              event.callId,
            ],
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          return context.updateCallIds.length === context.existingCustomers.length;
        },
        target: 'writeMissingVips',
      },
    },
    writeMissingVips: {
      entry: toolCall('fs.write_file', ({ context }) => ({
        path: 'notes/missing-vips.txt',
        content: context.missingEmails.join('\n') + (context.missingEmails.length > 0 ? '\n' : ''),
      })),
      on: {
        TOOL_RESULT: {
          target: 'done',
          actions: assign({ writeStatus: 'success' }),
        },
        TOOL_DENIED: {
          target: 'done',
          actions: assign({ writeStatus: 'write denied' }),
        },
        TOOL_ERROR: {
          target: 'done',
          actions: assign({ writeStatus: 'write error' }),
        },
      },
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    vipEmailsProcessed: context.vipEmails.length,
    goldTierUpdated: context.existingCustomers.length,
    missingVipsFound: context.missingEmails.length,
    missingVips: context.missingEmails,
    writeStatus: context.writeStatus,
  }),
});

