import { setup, assign } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'goldCustomersOrders',
  context: {
    customers: [],
    orders: [],
    results: []
  },
  initial: 'getGoldCustomers',
  states: {
    getGoldCustomers: {
      entry: toolCall('mongo.find', () => ({
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'customers',
        query: { tier: 'gold' }
      })),
      on: {
        TOOL_RESULT: {
          target: 'getOrders',
          actions: assign({
            customers: ({ event }) => {
              const result = event.result;
              if (typeof result === 'string') {
                return JSON.parse(result);
              }
              return result || [];
            }
          })
        },
        TOOL_ERROR: { target: 'failed' }
      }
    },
    getOrders: {
      entry: toolCall('mongo.find', () => ({
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'orders',
        query: { status: { $ne: 'cancelled' } }
      })),
      on: {
        TOOL_RESULT: {
          target: 'calculateTotals',
          actions: assign({
            orders: ({ event }) => {
              const result = event.result;
              if (typeof result === 'string') {
                return JSON.parse(result);
              }
              return result || [];
            }
          })
        },
        TOOL_ERROR: { target: 'failed' }
      }
    },
    calculateTotals: {
      type: 'final',
      entry: assign({
        results: ({ context }) => {
          // Group orders by customer email and sum totals
          const emailToTotal = {};

          context.orders.forEach(order => {
            if (order.customerEmail && order.total) {
              if (!emailToTotal[order.customerEmail]) {
                emailToTotal[order.customerEmail] = 0;
              }
              emailToTotal[order.customerEmail] += order.total;
            }
          });

          // Create results for gold-tier customers only
          const results = context.customers
            .map(customer => ({
              email: customer.email,
              total: (emailToTotal[customer.email] || 0).toFixed(2)
            }))
            .sort((a, b) => a.email.localeCompare(b.email));

          return results;
        }
      })
    },
    failed: { type: 'final' }
  },
  output: ({ context }) => context.results
});

import { setup, assign } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'goldCustomersOrdersTotals',
  context: {
    results: []
  },
  initial: 'aggregateData',
  states: {
    aggregateData: {
      entry: toolCall('mongo.aggregate', () => ({
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'customers',
        pipeline: [
          // Match gold-tier customers
          { $match: { tier: 'gold' } },
          // Lookup orders for each customer
          {
            $lookup: {
              from: 'orders',
              localField: 'email',
              foreignField: 'customerEmail',
              as: 'customerOrders'
            }
          },
          // Unwind the orders array
          { $unwind: { path: '$customerOrders', preserveNullAndEmptyArrays: true } },
          // Filter out cancelled orders
          {
            $match: {
              $or: [
                { 'customerOrders.status': { $ne: 'cancelled' } },
                { customerOrders: { $exists: false } }
              ]
            }
          },
          // Group by email and sum totals
          {
            $group: {
              _id: '$email',
              totalValue: { $sum: '$customerOrders.total' }
            }
          },
          // Sort by email
          { $sort: { _id: 1 } }
        ]
      })),
      on: {
        TOOL_RESULT: {
          target: 'formatResults',
          actions: assign({
            results: ({ event }) => {
              const result = event.result;
              const docs = Array.isArray(result) ? result : result?.documents || [];
              return docs;
            }
          })
        },
        TOOL_ERROR: { target: 'failed' }
      }
    },
    formatResults: {
      type: 'final',
      entry: assign({
        results: ({ context }) => {
          return context.results.map(doc => {
            const total = (doc.totalValue || 0).toFixed(2);
            return `${doc._id}: $${total}`;
          });
        }
      })
    },
    failed: { type: 'final' }
  },
  output: ({ context }) => context.results
});

