      entry: toolCall('mongo.aggregate', () => ({
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'customers',
        pipeline: [
          // Match gold-tier customers
          { $match: { tier: 'gold' } },
          // Lookup orders for each customer
          {
            $lookup: {
              from: 'orders',
              localField: 'email',
              foreignField: 'customerEmail',
              as: 'customerOrders'
            }
          },
          // Unwind the orders array
          { $unwind: { path: '$customerOrders', preserveNullAndEmptyArrays: true } },
          // Filter out cancelled orders
          {
            $match: {
              $or: [
                { 'customerOrders.status': { $ne: 'cancelled' } },
                { customerOrders: { $exists: false } }
              ]
            }
          },
          // Group by email and sum totals
          {
            $group: {
              _id: '$email',
              totalValue: { $sum: '$customerOrders.total' }
            }
          },
          // Sort by email
          { $sort: { _id: 1 } }
        ]
      })),
      on: {
        TOOL_RESULT: {
          target: 'formatResults',
          actions: assign({
            results: ({ event }) => {
              const result = event.result;
              const docs = Array.isArray(result) ? result : result?.documents || [];
              return docs;
            }
          })
        },
        TOOL_ERROR: { target: 'failed' }
      }
    },
    formatResults: {
      type: 'final',
      entry: assign({
        results: ({ context }) => {
          return context.results.map(doc => {
            const total = (doc.totalValue || 0).toFixed(2);
            return `${doc._id}: $${total}`;
          });
        }
      })
    },
    failed: { type: 'final' }
  },
  output: ({ context }) => context.results
});

