export default setup({}).createMachine({
  context: { n: 0, done: 0 },
  initial: 'w',
  states: {
    w: {
      entry: enqueueActions(({ enqueue }) => {
        Object.entries(items).forEach(([k, l]) => {
          enqueue(toolCall('github.issue_write', { method: 'update', owner: 'acme', repo: 'widgets', issue_number: Number(k), labels: [...l, 'stale'] }, { id: 'i' + k }));
        });
      }),
      on: {
        TOOL_RESULT: { actions: assign({ done: ({ context }) => context.done + 1 }) },
        TOOL_DENIED: { actions: assign({ done: ({ context }) => context.done + 1 }) },
        TOOL_ERROR: { actions: assign({ done: ({ context }) => context.done + 1 }) },
      },
      always: { guard: ({ context }) => context.done === 12, target: 'd' },
    },
    d: { type: 'final' },
  },
