import { setup, assign, enqueueActions } from 'xstate';
import { toolCall } from '@astral-mcp/tools';
const nums=[146,144,142,140,139,137,12,11,135,10,134,8,132,131,128,127,125,124,123,121,120,117,116,114,113,111];
const parse=r=>typeof r==='string'?JSON.parse(r):r;
export default setup({}).createMachine({
  id:'c',
  context:{done:0,hits:[],big:[],cdone:0,errs:[]},
  initial:'reading',
  states:{
    reading:{
      entry:enqueueActions(({enqueue})=>{nums.forEach(n=>enqueue(toolCall('github.pull_request_read',{method:'get_files',owner:'acme',repo:'widgets',pullNumber:n,perPage:100},{id:'r'+n})));}),
      on:{
        TOOL_RESULT:{actions:assign(({context,event})=>{
          const n=Number(event.callId.slice(1));let f=[];
          try{f=parse(event.result)}catch(e){}
          const hit=f.some(x=>x.filename.startsWith('src/export/'));
          return {done:context.done+1,hits:hit?[...context.hits,n]:context.hits,big:f.length>=100?[...context.big,n]:context.big};
        })},
        TOOL_ERROR:{actions:assign({done:({context})=>context.done+1,errs:({context,event})=>[...context.errs,event.callId]})},
      },
      always:{guard:({context})=>context.done===nums.length,target:'commenting'},
    },
    commenting:{
      entry:enqueueActions(({context,enqueue})=>{context.hits.forEach(n=>enqueue(toolCall('github.add_issue_comment',{owner:'acme',repo:'widgets',issue_number:n,body:'Please add a CHANGELOG entry for the export changes.'},{id:'c'+n})));}),
      on:{
        TOOL_RESULT:{actions:assign({cdone:({context})=>context.cdone+1})},
        TOOL_DENIED:{actions:assign({cdone:({context})=>context.cdone+1})},
        TOOL_ERROR:{actions:assign({cdone:({context})=>context.cdone+1})},
      },
      always:{guard:({context})=>context.cdone===context.hits.length,target:'done'},
    },
    done:{type:'final'},
  },
  output:({context})=>context,
});

