import { toolCall } from '@astral-mcp/tools';
const ex=['src/api/routes.ts','src/db/pool.ts','src/export/xml.ts','src/cli/args.ts','src/ui/chart.tsx','docs/api.md'];
const miss=['src/cache/lru.ts','src/export/pdf.ts','src/perf/bench.ts','scripts/license.sh'];
export default setup({}).createMachine({
  context:{n:0},initial:'w',
  states:{w:{
    entry:enqueueActions(({enqueue})=>{
      ex.forEach((p,i)=>enqueue(toolCall('github.issue_write',{method:'create',owner:'acme',repo:'widgets',title:'Fix '+p,body:'Failing check on PR #139 reports '+p+'.'},{id:'i'+i})));
      miss.forEach((p,i)=>enqueue(toolCall('github.add_issue_comment',{owner:'acme',repo:'widgets',issue_number:139,body:'File reported by failing check does not exist in the project: '+p},{id:'c'+i})));
    }),
    on:{'*':{actions:enqueueActions(({context,event,enqueue})=>{})},
      TOOL_RESULT:{actions:({context})=>{context.n++}},
      TOOL_ERROR:{actions:({context})=>{context.n++}},
      TOOL_DENIED:{actions:({context})=>{context.n++}}},
    always:{guard:({context})=>context.n>=10,target:'d'}},
  d:{type:'final'}}
});

