import { setup, enqueueActions } from 'xstate';
import { toolCall } from '@astral-mcp/tools';
const ex=['src/api/routes.ts','src/db/pool.ts','src/export/xml.ts','src/cli/args.ts','src/ui/chart.tsx','docs/api.md'];
const miss=['src/cache/lru.ts','src/export/pdf.ts','src/perf/bench.ts','scripts/license.sh'];
export default setup({}).createMachine({
  context:{n:0},initial:'w',
  states:{w:{
    entry:enqueueActions(({enqueue})=>{
      ex.forEach((p,i)=>enqueue(toolCall('github.issue_write',{method:'create',owner:'acme',repo:'widgets',title:'Fix '+p,body:'Failing check on PR #139 reports '+p+'.'},{id:'i'+i})));
      miss.forEach((p,i)=>enqueue(toolCall('github.add_issue_comment',{owner:'acme',repo:'widgets',issue_number:139,body:'File reported by failing check does not exist in the project: '+p},{id:'c'+i})));
    }),
    on:{'*':{actions:enqueueActions(({context,event,enqueue})=>{})},
      TOOL_RESULT:{actions:({context})=>{context.n++}},
      TOOL_ERROR:{actions:({context})=>{context.n++}},
      TOOL_DENIED:{actions:({context})=>{context.n++}}},
    always:{guard:({context})=>context.n>=10,target:'d'}},
  d:{type:'final'}}
});

import { setup, assign } from 'xstate';
import { toolCall } from '@astral-mcp/tools';
export default setup({}).createMachine({
  initial:'a', context:{o:{}},
  states:{
    a:{entry:toolCall('fs.read_file',{path:'notes/vip.txt'}),on:{TOOL_RESULT:{target:'b',actions:assign({o:({event})=>({vip:event.result})})},TOOL_ERROR:'z'}},
    b:{entry:toolCall('mongo.list-databases',{}),on:{TOOL_RESULT:{target:'c',actions:assign({o:({context,event})=>({...context.o,db:event.result})})},TOOL_ERROR:'z'}},
    c:{entry:toolCall('fs.list_allowed_directories',{}),on:{TOOL_RESULT:{target:'z',actions:assign({o:({context,event})=>({...context.o,d:event.result})})},TOOL_ERROR:'z'}},
    z:{type:'final'}
  },
  output:({context})=>context.o
});

import { setup } from 'xstate';
import { toolCall } from '@astral-mcp/tools';
export default setup({}).createMachine({
  initial:'a',
  states:{
    a:{entry:[
      toolCall('mongo.update-many',{connectionId:'preconfigured',database:'shop',collection:'customers',filter:{email:{$in:['bob@example.com','kemal.arslan@example.com','nadia.haddad@example.com','quinn.avery@example.com','uma.patel@example.com','bianca.neri@example.com','emil.berg@example.com','sofia.lund@example.com']}},update:{$set:{tier:'gold'}}},{id:'m'}),
      toolCall('fs.write_file',{path:'notes/missing-vips.txt',content:'zoe.park@example.com\ngrace@example.org\nliam.byrne@example.com\noliver.grant@example.com\n'},{id:'f'})
    ],
    on:{TOOL_RESULT:{},TOOL_ERROR:{},TOOL_DENIED:{}},
    after:{1:'z'}},
    z:{type:'final'}
  }
});

import { setup, assign } from 'xstate';
import { toolCall } from '@astral-mcp/tools';
export default setup({}).createMachine({
  initial:'a', context:{n:0,r:[]},
  states:{
    a:{entry:[
      toolCall('mongo.update-many',{connectionId:'preconfigured',database:'shop',collection:'customers',filter:{email:{$in:['bob@example.com','kemal.arslan@example.com','nadia.haddad@example.com','quinn.avery@example.com','uma.patel@example.com','bianca.neri@example.com','emil.berg@example.com','sofia.lund@example.com']}},update:{$set:{tier:'gold'}}},{id:'m'}),
      toolCall('fs.write_file',{path:'notes/missing-vips.txt',content:'zoe.park@example.com\ngrace@example.org\nliam.byrne@example.com\noliver.grant@example.com\n'},{id:'f'})
    ],
    on:{
      TOOL_RESULT:{actions:assign({n:({context})=>context.n+1,r:({context,event})=>[...context.r,event.result]})},
      TOOL_ERROR:{actions:assign({n:({context})=>context.n+1,r:({context,event})=>[...context.r,'err']})},
      TOOL_DENIED:{actions:assign({n:({context})=>context.n+1,r:({context,event})=>[...context.r,'denied']})}},
    always:{guard:({context})=>context.n===2,target:'z'}},
    z:{type:'final'}
  },
  output:({context})=>context.r
});

