import { setup, assign, enqueueActions } from 'xstate';
import { toolCall } from '@astral-mcp/tools';
const names="api-gateway auth billing cart catalog checkout email fraud geo image inventory ledger loyalty media notify orders payments pricing profile queue ranking recs reviews search session shipping tax wishlist".split(' ');
export default setup({}).createMachine({
  context:{counts:{},n:0},
  initial:'r',
  states:{
    r:{
      entry: enqueueActions(({enqueue})=>{names.forEach((n,i)=>enqueue(toolCall('fs.read_file',{path:'logs/services/'+n+'.log'},{id:'f'+i})));}),
      on:{
        TOOL_RESULT:{actions:assign(({context,event})=>{
          const i=+event.callId.slice(1);
          const t=typeof event.result==='string'?event.result:(event.result&&event.result.content)||JSON.stringify(event.result);
          const c=t.split('\n').filter(l=>l.split(/\s+/)[1]==='ERROR').length;
          return {counts:{...context.counts,[names[i]+'.log']:c},n:context.n+1};
        })},
        TOOL_ERROR:{actions:assign(({context,event})=>({counts:{...context.counts,[names[+event.callId.slice(1)]+'.log']:'error'},n:context.n+1}))}
      },
      always:{guard:({context})=>context.n===names.length,target:'d'}
    },
    d:{type:'final'}
  },
  output:({context})=>context.counts
});

